#include "simp/SemanticAnalyzer.hpp"

#include <unordered_set>

namespace simp {

const FieldDeclaration* SemanticAnalyzer::findField(const ClassDeclaration& declaration,
                                                    const std::string& name) const {
    if (countFields(declaration, name) != 1) return nullptr;
    for (const auto& field : declaration.fields) {
        if (field.name == name) return &field;
    }
    for (const auto& baseName : declaration.baseClassNames) {
        const auto base = classes_.find(baseName);
        if (base == classes_.end() || countFields(*base->second, name) == 0) continue;
        return findField(*base->second, name);
    }
    return nullptr;
}

std::size_t SemanticAnalyzer::countFields(const ClassDeclaration& declaration,
                                          const std::string& name) const {
    std::size_t count = 0;
    for (const auto& field : declaration.fields) {
        if (field.name == name) ++count;
    }
    if (count != 0) return count;
    for (const auto& baseName : declaration.baseClassNames) {
        const auto base = classes_.find(baseName);
        if (base != classes_.end()) count += countFields(*base->second, name);
    }
    return count;
}

const MethodDeclaration* SemanticAnalyzer::findMethod(const ClassDeclaration& declaration,
                                                      const std::string& name) const {
    for (const auto& method : declaration.methods) {
        if (method.name == name && !method.constructor) return &method;
    }
    if (countMethods(declaration, name) != 1) return nullptr;
    for (const auto& baseName : declaration.baseClassNames) {
        const auto base = classes_.find(baseName);
        if (base != classes_.end() && countMethods(*base->second, name) != 0) {
            return findMethod(*base->second, name);
        }
    }
    return nullptr;
}

std::size_t SemanticAnalyzer::countMethods(const ClassDeclaration& declaration,
                                           const std::string& name) const {
    for (const auto& method : declaration.methods) {
        if (method.name == name && !method.constructor) return 1;
    }
    std::size_t count = 0;
    for (const auto& baseName : declaration.baseClassNames) {
        const auto base = classes_.find(baseName);
        if (base != classes_.end()) count += countMethods(*base->second, name);
    }
    return count;
}

bool SemanticAnalyzer::isSubclassOf(const std::string& type, const std::string& base) const {
    const auto found = classes_.find(type);
    if (found == classes_.end()) return false;
    std::vector<const ClassDeclaration*> pending{found->second};
    std::unordered_set<std::string> visited;
    while (!pending.empty()) {
        const auto* current = pending.back();
        pending.pop_back();
        if (!visited.emplace(current->name).second) continue;
        for (const auto& baseName : current->baseClassNames) {
            if (baseName == base) return true;
            const auto parent = classes_.find(baseName);
            if (parent != classes_.end()) pending.push_back(parent->second);
        }
    }
    return false;
}

bool SemanticAnalyzer::isAssignable(const std::string& target,
                                    const std::string& source) const {
    if (target == source) return true;
    const auto found = classes_.find(source);
    if (classes_.find(target) == classes_.end() || found == classes_.end() ||
        !isSubclassOf(source, target)) return false;
    const auto countPaths = [this, &target](const auto& self,
                                            const ClassDeclaration& owner) -> std::size_t {
        std::size_t count = 0;
        for (const auto& baseName : owner.baseClassNames) {
            if (baseName == target) {
                ++count;
            } else {
                const auto base = classes_.find(baseName);
                if (base != classes_.end()) count += self(self, *base->second);
            }
        }
        return count;
    };
    if (countPaths(countPaths, *found->second) != 1) return false;
    auto* current = found->second;
    while (current != nullptr && current->name != target) {
        if (current->baseClassNames.empty()) return false;
        current = classes_.at(current->baseClassNames.front());
    }
    return current != nullptr;
}

std::vector<const FieldDeclaration*> SemanticAnalyzer::inheritedFields(
    const ClassDeclaration& declaration) const {
    std::vector<const FieldDeclaration*> fields;
    for (const auto& baseName : declaration.baseClassNames) {
        const auto base = classes_.find(baseName);
        if (base != classes_.end()) {
            auto inherited = inheritedFields(*base->second);
            fields.insert(fields.end(), inherited.begin(), inherited.end());
        }
    }
    for (const auto& field : declaration.fields) fields.push_back(&field);
    return fields;
}

} // namespace simp
